components.css:
.ds-button{
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  min-height: 55px;
  padding: 16px 22px;
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 750;
  line-height: 1.4;
  transition:
    background 0.25s,
    color 0.25s,
    border-color 0.25s;
}
.ds-button svg{
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-button:hover svg:last-child{
  transform: translateX(5px);
}
.ds-button-gold{
  background: var(--gold);
  color: var(--ink);
}
.ds-button-gold:hover{
  background: #ecdaa9;
}.ds-button{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);cursor:pointer}.ds-button:focus-visible{outline:2px solid var(--gold,#ddc185);outline-offset:6px;}

